import{_ as t,o,c as a,ag as s}from"./chunks/framework.BIas3y6W.js";const p=JSON.parse('{"title":"Week 13 lab — Attack, fix, connect","description":"","frontmatter":{"source":"weeks/13-data-and-access/lab.md"},"headers":[],"relativePath":"weeks/13-data-and-access/lab.md","filePath":"weeks/13-data-and-access/lab.md"}'),n={name:"weeks/13-data-and-access/lab.md"};function r(i,e,l,d,c,h){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="week-13-lab--attack-fix-connect" tabindex="-1">Week 13 lab — Attack, fix, connect <a class="header-anchor" href="#week-13-lab--attack-fix-connect" aria-label="Permalink to &quot;Week 13 lab — Attack, fix, connect&quot;">​</a></h1><blockquote><p>Two studios. <strong>Studio A:</strong> break a practice database with its public key, then fix it with row-level security. <strong>Studio B:</strong> connect your capstone to Supabase the safe way, attack your own table, and wire up one feature with the agent. Do the <strong>Core</strong> parts first. <strong>If time</strong> parts are optional. Work in the <a href="./../../resources/safe-loop.html">Safe Loop</a> and commit after every part.</p></blockquote><p><strong>AI-use key:</strong> 🟢 AI on: use AI freely, in the Safe Loop · 🟡 AI limited: the AI may explain and critique, but you decide and write · 🔴 AI off: no AI tools at all, including code completions.</p><p><strong>What you need:</strong> a free Supabase account and the empty <code>rls-lab</code> project you made before class (<a href="./../../TOOLS.html">Tool Handout</a>), and (Studio B) your capstone repo in a Codespace. The attack page is hosted, so there&#39;s nothing to install for Studio A.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Everything here runs against <strong>your own</strong> practice project and <strong>your own</strong> capstone. Never point these tools at a database or site you don&#39;t own. Use made-up data only.</p></div><hr><h2 id="studio-a--attack-and-fix-75-min" tabindex="-1">Studio A — Attack and fix (75 min) <a class="header-anchor" href="#studio-a--attack-and-fix-75-min" aria-label="Permalink to &quot;Studio A — Attack and fix (75 min)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Time</th><th>Part</th><th>Core or If time</th></tr></thead><tbody><tr><td>0:00–0:05</td><td>Recap: last week&#39;s most-missed exit-ticket question</td><td></td></tr><tr><td>0:05–0:25</td><td>Talk (<a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/slides/week-13.html" target="_blank" rel="noreferrer">slides</a>) and live attack demo</td><td></td></tr><tr><td>0:25–1:10</td><td><a href="#part-a1--rls-attack-lab-core-45-min">Part A1 — RLS Attack Lab</a></td><td>Core, 45 min</td></tr><tr><td>1:10–1:15</td><td>Checkpoint share: your before/after table, and why a blocked update says &quot;0 rows&quot;</td><td></td></tr></tbody></table><h3 id="part-a1--rls-attack-lab-core-45-min" tabindex="-1">Part A1 — RLS Attack Lab (Core, 45 min) <a class="header-anchor" href="#part-a1--rls-attack-lab-core-45-min" aria-label="Permalink to &quot;Part A1 — RLS Attack Lab (Core, 45 min)&quot;">​</a></h3><p>🟢 AI on, if you want explanations. Big idea: with the public key and no row-level security (RLS), anyone can read and change every row. You prove it, then lock it down. The lab runs whole, in this studio.</p><h4 id="a11-open-your-practice-project-3-min" tabindex="-1">A1.1 Open your practice project (3 min) <a class="header-anchor" href="#a11-open-your-practice-project-3-min" aria-label="Permalink to &quot;A1.1 Open your practice project (3 min)&quot;">​</a></h4><ol><li>Open the <code>rls-lab</code> project you created before class in the Supabase dashboard.</li><li>Didn&#39;t make one? Create a <strong>new project</strong> on the free plan now, call it <code>rls-lab</code>, pick any region and a database password you won&#39;t need again, and start A1.2 while it finishes setting up.</li></ol><p>✅ <strong>Checkpoint:</strong> you see the project dashboard, with <strong>SQL Editor</strong> and <strong>Table Editor</strong> in the left-hand menu.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Menus move. If a name here doesn&#39;t match what you see, ask your assistant &quot;Where is the SQL Editor in the current Supabase dashboard?&quot; or search the Supabase docs.</p></div><h4 id="a12-create-the-vulnerable-table-7-min" tabindex="-1">A1.2 Create the vulnerable table (7 min) <a class="header-anchor" href="#a12-create-the-vulnerable-table-7-min" aria-label="Permalink to &quot;A1.2 Create the vulnerable table (7 min)&quot;">​</a></h4><ol><li>Open <strong>SQL Editor</strong> → <strong>New query</strong>.</li><li>Open <a href="https://github.com/Boyu-Zhang-UOI/vc101-rls-lab/blob/main/setup.sql" target="_blank" rel="noreferrer">setup.sql</a> from the RLS Attack Lab kit, copy <strong>all</strong> of it, paste it in, and click <strong>Run</strong>. Supabase may ask you to confirm because the script contains <code>drop table</code>. Confirm: this is your practice project.</li><li>Open <strong>Database → Advisors → Security</strong>. You should see an error called <strong>&quot;RLS Disabled in Public&quot;</strong>, warning that anyone with your project URL can read, edit and delete all data in the table. The Table Editor may also mark the table <strong>Unrestricted</strong>.</li></ol><p>✅ <strong>Checkpoint:</strong> the <code>guestbook</code> table has 6 rows, and Supabase is warning you that RLS is off. That warning is the whole point.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Supabase now protects new tables in two ways: tables made in the Table Editor get RLS on, and from 30 October 2026 new tables get <strong>no grants</strong> (no permission for the public roles to use them at all). <code>setup.sql</code> undoes both on purpose, with explicit <code>grant</code>s and <code>disable row level security</code>, so the vulnerable state is the same in every project. Real leaks happen the same way: someone, or an agent, turns the protections off.</p></div><h4 id="a13-get-your-keys-5-min" tabindex="-1">A1.3 Get your keys (5 min) <a class="header-anchor" href="#a13-get-your-keys-5-min" aria-label="Permalink to &quot;A1.3 Get your keys (5 min)&quot;">​</a></h4><ol><li>Click <strong>Connect</strong> at the top of the dashboard, or go to <strong>Settings → API Keys</strong>.</li><li>Copy two things into a scratch note (not a file in a repo): <ul><li>the <strong>Project URL</strong> (looks like <code>https://abcdxyz.supabase.co</code>)</li><li>the <strong>publishable</strong> key (starts <code>sb_publishable_</code>)</li></ul></li><li>Leave the <strong>secret</strong> key alone (starts <code>sb_secret_</code>). You never need it in this course&#39;s front end.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>If you only see a legacy <strong>anon</strong> key (a long string starting <code>eyJ</code>), look for the tab with publishable and secret keys and create a publishable key there. Supabase is retiring the legacy <code>anon</code> and <code>service_role</code> keys by the end of 2026.</p></div><p>✅ <strong>Checkpoint:</strong> you have a Project URL and a publishable key in a scratch note.</p><h4 id="a14-attack-the-table-with-only-the-public-key-12-min" tabindex="-1">A1.4 Attack the table with only the public key (12 min) <a class="header-anchor" href="#a14-attack-the-table-with-only-the-public-key-12-min" aria-label="Permalink to &quot;A1.4 Attack the table with only the public key (12 min)&quot;">​</a></h4><p>You use a tester page that does what any stranger could build in an afternoon.</p><ol><li>Open the hosted <a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/tools/rls-attack.html" target="_blank" rel="noreferrer">RLS attack page</a>. It runs in your browser and talks straight to your Supabase project.</li><li>Read the banner. Paste your <strong>Project URL</strong> and <strong>publishable key</strong>, leave the table as <code>guestbook</code>, and click <strong>Connect</strong>.</li><li>Run each button and note the label the page gives each result (open <strong>How to read the results</strong> on the page for what each label means): <ul><li><strong>Read all rows</strong>: you see all 6 rows, <em>including the 2 private notes</em> (<code>is_public = false</code>).</li><li><strong>Insert a row</strong>: works. Try again with <code>is_public</code> set to <code>false</code>: also works.</li><li><strong>Update row #1</strong>: works; the message changes.</li><li><strong>Delete newest row</strong>: works; a row disappears.</li></ul></li></ol><p>✅ <strong>Checkpoint:</strong> with only the public key, you read private notes and changed and deleted data. This is the state UpGuard found in 16,326 databases. Fill in the &quot;Before fix&quot; column in A1.6.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>The page keeps your URL and key <strong>in memory only</strong> and never saves them. Click <strong>Forget key</strong> when you&#39;re done, or close the tab. The page refuses keys that look secret, but check the prefix yourself anyway: only ever paste a key starting <code>sb_publishable_</code>.</p></div><h4 id="a15-fix-it-with-row-level-security-8-min" tabindex="-1">A1.5 Fix it with row-level security (8 min) <a class="header-anchor" href="#a15-fix-it-with-row-level-security-8-min" aria-label="Permalink to &quot;A1.5 Fix it with row-level security (8 min)&quot;">​</a></h4><ol><li>Back in <strong>SQL Editor</strong> → <strong>New query</strong>, open <a href="https://github.com/Boyu-Zhang-UOI/vc101-rls-lab/blob/main/fix.sql" target="_blank" rel="noreferrer">fix.sql</a>, paste all of it, and <strong>Run</strong>.</li><li>Read the result of its last query: the table&#39;s RLS status (<code>rls_enabled</code> = true) and the two policies it created. Say each policy out loud in plain words. If you know SQL or Python: the <code>using</code> rule is a filter added to every query, and the <code>with check</code> rule tests every new row.</li><li>Re-open <strong>Database → Advisors → Security</strong>. The &quot;RLS Disabled&quot; error should be gone.</li></ol><p>✅ <strong>Checkpoint:</strong> RLS is on and two policies exist: one for reading public rows, one for adding a valid public row.</p><h4 id="a16-re-run-the-attack-and-compare-10-min" tabindex="-1">A1.6 Re-run the attack and compare (10 min) <a class="header-anchor" href="#a16-re-run-the-attack-and-compare-10-min" aria-label="Permalink to &quot;A1.6 Re-run the attack and compare (10 min)&quot;">​</a></h4><p>Go back to the attack page (reconnect if needed) and run every button again. Fill in this table:</p><table tabindex="0"><thead><tr><th>Action (public key)</th><th>Before fix</th><th>After fix</th></tr></thead><tbody><tr><td>Read all rows</td><td></td><td></td></tr><tr><td>Insert a normal public row</td><td></td><td></td></tr><tr><td>Insert a private row (<code>is_public = false</code>)</td><td></td><td></td></tr><tr><td>Insert a 1,000-character message</td><td></td><td></td></tr><tr><td>Update row #1</td><td></td><td></td></tr><tr><td>Delete newest row</td><td></td><td></td></tr></tbody></table><p>What you should find after the fix: reading shows <strong>only the 4 public rows</strong>; a normal public insert still works; a private or over-long insert is <strong>refused</strong> with <em>&quot;new row violates row-level security policy&quot;</em>; update and delete report <strong>0 rows changed and no error</strong>.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Read the result carefully. There are three different &quot;blocked&quot; answers, and they mean different things:</p><ul><li><strong>&quot;permission denied&quot;</strong> (the page says <strong>REFUSED: NO GRANT</strong>): the role has no <strong>grant</strong> for that operation. Lock 1 stopped it.</li><li><strong>&quot;new row violates row-level security policy&quot;</strong> (<strong>REFUSED BY RLS</strong>): an insert or update broke a policy&#39;s rule. Lock 2 stopped it.</li><li><strong>No error, 0 rows</strong> (<strong>0 ROWS (FILTERED)</strong>): RLS hid every row you weren&#39;t allowed to touch, so nothing matched. Also blocked, silently.</li></ul><p>So <strong>always check how many rows changed</strong>, not only whether there was an error. And &quot;0 rows&quot; only proves something if the table really holds rows the public shouldn&#39;t see. Labels starting <strong>ERROR</strong>, and <strong>REFUSED BY A COLUMN RULE</strong>, aren&#39;t security results: they mean a setup problem or bad data.</p></div><p>✅ <strong>Checkpoint:</strong> your before/after table is filled in, and you can explain why update says &quot;0 rows&quot; instead of an error.</p><p>Clean up: keep the practice project if you might reuse it, or delete it from its settings page later. Paste your before/after table into your capstone&#39;s <code>SECURITY_CHECKLIST.md</code> under &quot;What I found and fixed&quot;.</p><h4 id="troubleshooting-studio-a" tabindex="-1">Troubleshooting (Studio A) <a class="header-anchor" href="#troubleshooting-studio-a" aria-label="Permalink to &quot;Troubleshooting (Studio A)&quot;">​</a></h4><ul><li><strong>The attack still works after the fix:</strong> you probably pasted a secret key, which skips RLS. Check the prefix: only <code>sb_publishable_</code> belongs here. The page refuses keys that look secret, but make checking the prefix your habit.</li><li><strong>&quot;permission denied&quot; before the fix:</strong> <code>setup.sql</code> didn&#39;t run to the end, so the grants are missing. Run the whole file again; it resets the table.</li><li><strong>A label starting ERROR:</strong> a wrong URL, key, table or column name, or a paused project. Fix the setup and try again; it isn&#39;t a security result.</li><li><strong>The free plan won&#39;t let you create another project:</strong> delete an old one, or reuse a project you already have after running <code>drop table if exists public.guestbook;</code>.</li><li><strong>The hosted attack page won&#39;t load:</strong> open <code>attack.html</code> from the <a href="https://github.com/Boyu-Zhang-UOI/vc101-rls-lab" target="_blank" rel="noreferrer">RLS Attack Lab kit</a> on your own computer, or serve the kit folder in a Codespace with <code>python3 -m http.server 8000</code>.</li></ul><hr><h2 id="studio-b--connect-your-capstone-75-min" tabindex="-1">Studio B — Connect your capstone (75 min) <a class="header-anchor" href="#studio-b--connect-your-capstone-75-min" aria-label="Permalink to &quot;Studio B — Connect your capstone (75 min)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Time</th><th>Part</th><th>Core or If time</th></tr></thead><tbody><tr><td>0:00–0:05</td><td>Show and tell: two capstones; &quot;where is your data, and who can read it?&quot;</td><td></td></tr><tr><td>0:05–0:45</td><td><a href="#part-b1--connect-your-capstone-to-supabase-core-40-min">Part B1 — Connect your capstone to Supabase</a></td><td>Core, 40 min</td></tr><tr><td>0:45–1:05</td><td><a href="#part-b2--connect-one-feature-with-the-agent-core-20-min">Part B2 — Connect one feature with the agent</a>: project time and catch-up help</td><td>Core, 20 min</td></tr><tr><td></td><td><a href="#part-b3--per-user-rows-or-attack-from-the-console-if-time">Part B3 — Per-user rows, or attack from the Console</a></td><td>If time</td></tr><tr><td>1:05–1:15</td><td>Exit ticket, 🔴 AI off</td><td></td></tr></tbody></table><h3 id="part-b1--connect-your-capstone-to-supabase-core-40-min" tabindex="-1">Part B1 — Connect your capstone to Supabase (Core, 40 min) <a class="header-anchor" href="#part-b1--connect-your-capstone-to-supabase-core-40-min" aria-label="Permalink to &quot;Part B1 — Connect your capstone to Supabase (Core, 40 min)&quot;">​</a></h3><p>The worked example for feature type (b), a database with access rules. You set up the two locks yourself, attack them, then (Part B2) let the agent wire up the page.</p><p>Start on a branch, as in week 12, so the feature reaches <code>main</code> through a pull request:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> switch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature/data</span></span></code></pre></div><p><strong>Not using a database in your capstone?</strong> Do this part anyway on a practice branch you won&#39;t merge (<code>git switch -c practice/supabase</code> instead): it&#39;s the only time the course walks through it, and walkthrough 3 in week 14 asks everyone where authorization is enforced. If you hit the free plan&#39;s project limit, reuse your <code>rls-lab</code> project after running <code>drop table public.guestbook;</code>.</p><p>The capstone starter has three files for this. The starter README&#39;s <a href="https://github.com/Boyu-Zhang-UOI/vc101-capstone-starter/blob/main/README.md#feature-patterns" target="_blank" rel="noreferrer">feature patterns</a> explain each one:</p><table tabindex="0"><thead><tr><th>File</th><th>What it holds</th><th>Public?</th></tr></thead><tbody><tr><td><code>public/config.js</code> (copied from <code>public/config.example.js</code>)</td><td>Your Project URL and <strong>publishable</strong> key</td><td>Yes, by design. Committed</td></tr><tr><td><code>public/lib/db.js</code></td><td><code>getDb()</code>, which gives your page one Supabase client. It loads the Supabase library from the jsDelivr <a href="./../../resources/glossary.html#cdn">CDN</a> (a public server that hosts copies of open-source code, so a page can load it with one <code>import</code> line) and refuses to start with a secret key</td><td>Yes</td></tr><tr><td><code>supabase/policies.sql</code></td><td>Your tables, their grants and their RLS policies, plus a check query at the end</td><td>Yes. A reviewer reads it to see your rules</td></tr></tbody></table><h4 id="b11-decide-who-may-do-what-10-min" tabindex="-1">B1.1 Decide who may do what (10 min) <a class="header-anchor" href="#b11-decide-who-may-do-what-10-min" aria-label="Permalink to &quot;B1.1 Decide who may do what (10 min)&quot;">​</a></h4><p>🔴 AI off for the decision; this is your app&#39;s authorization. Before any SQL, fill in this table in <code>SPEC.md</code> (or a comment at the top of <code>supabase/policies.sql</code>), one per table:</p><table tabindex="0"><thead><tr><th>Role</th><th>Read</th><th>Add</th><th>Change</th><th>Delete</th></tr></thead><tbody><tr><td>Anyone (publishable key, not signed in)</td><td></td><td></td><td></td><td></td></tr><tr><td>Signed-in user (only if you add sign-in)</td><td></td><td></td><td></td><td></td></tr></tbody></table><p><code>supabase/policies.sql</code> has two patterns to start from:</p><ul><li><strong>Pattern A, a public table</strong> (<code>messages</code>, like a guestbook): anyone may read every row and add a short one; nobody using the publishable key may change or delete one. Only for data you&#39;d be happy to see on a public notice board.</li><li><strong>Pattern B, private rows</strong> (<code>notes</code>): a signed-in user may read, add, change and delete only their own rows; anyone not signed in gets nothing. Needs sign-in (see Part B3).</li></ul><p>If any row could ever be private (a note, an email, a phone number), &quot;anyone may read&quot; is wrong: that&#39;s Pattern B.</p><p>✅ <strong>Checkpoint:</strong> you can say your rules in one sentence each, and you know which pattern you&#39;ll start from.</p><h4 id="b12-create-the-table-the-grants-and-the-policies-15-min" tabindex="-1">B1.2 Create the table, the grants and the policies (15 min) <a class="header-anchor" href="#b12-create-the-table-the-grants-and-the-policies-15-min" aria-label="Permalink to &quot;B1.2 Create the table, the grants and the policies (15 min)&quot;">​</a></h4><p>🟡 AI limited: the AI may explain any line or critique your file, but you decide the rules and must be able to explain every line.</p><ol><li>Create a Supabase project for your capstone (named after your app) and copy its Project URL and publishable key into your scratch note.</li><li>Open <code>supabase/policies.sql</code>. Keep the pattern that matches your B1.1 table, rename the table and columns to fit your app, and delete the other pattern. No data of your own yet? Keep Pattern A exactly as it is.</li><li>Find the three parts in what you kept and say each one in plain words: the <strong><code>grant</code></strong> lines (lock 1: may this role use the table at all?), <strong><code>enable row level security</code></strong>, and the <strong><code>create policy</code></strong> statements (lock 2: which rows?). Change the grants and policies so they match your B1.1 table exactly: no grant for anything your table says &quot;no&quot; to.</li><li>Paste the whole file into <strong>SQL Editor</strong> → <strong>New query</strong> and <strong>Run</strong>. Read the result of its last query: one line per table, with <code>rls_enabled</code>, its <code>api_grants</code> and its number of <code>policies</code>.</li></ol><p>✅ <strong>Checkpoint:</strong> every table shows <code>rls_enabled</code> = true, its <code>api_grants</code> match your B1.1 table (Pattern A unchanged shows only <code>INSERT</code> and <code>SELECT</code>), and there&#39;s at least one policy for each granted operation.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><strong>Never answer &quot;permission denied&quot; with a bare grant.</strong> If your app or an agent hits <code>permission denied for table …</code>, the fix is to add the grant <strong>in <code>supabase/policies.sql</code>, together with RLS on and a policy</strong>, then re-run the file. A line like <code>grant all on my_table to anon</code> on its own, with RLS off, rebuilds exactly the leak you attacked in Studio A. If an agent proposes it, stop and reject it.</p></div><h4 id="b13-put-the-url-and-publishable-key-in-publicconfigjs-5-min" tabindex="-1">B1.3 Put the URL and publishable key in <code>public/config.js</code> (5 min) <a class="header-anchor" href="#b13-put-the-url-and-publishable-key-in-publicconfigjs-5-min" aria-label="Permalink to &quot;B1.3 Put the URL and publishable key in \`public/config.js\` (5 min)&quot;">​</a></h4><ol><li><p>In the terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> public/config.example.js</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> public/config.js</span></span></code></pre></div></li><li><p>Paste your Project URL and publishable key where the file says.</p></li><li><p>Read the comment at the top of the file. Then write one sentence in your README&#39;s &quot;where each key lives&quot; section, in your own words, saying why this key is safe to publish (it&#39;s public by design; RLS and the grants protect the data).</p></li></ol><p>✅ <strong>Checkpoint:</strong> <code>public/config.js</code> holds a key starting <code>sb_publishable_</code> and nothing starting <code>sb_secret_</code>.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>This is the &quot;Not every key is a secret&quot; rule from the <a href="./#key-ideas">README</a>. The publishable key goes in <code>public/</code> and gets committed, because the deployed site needs it. Your LLM key and any secret key stay in <code>.env</code> and in Vercel&#39;s environment variables, never in <code>public/</code>.</p></div><h4 id="b14-attack-your-own-table-10-min" tabindex="-1">B1.4 Attack your own table (10 min) <a class="header-anchor" href="#b14-attack-your-own-table-10-min" aria-label="Permalink to &quot;B1.4 Attack your own table (10 min)&quot;">​</a></h4><p>Check first: prove the locks hold before any page code depends on them.</p><ol><li>Open the <a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/tools/rls-attack.html" target="_blank" rel="noreferrer">RLS attack page</a> again. Connect with your <strong>capstone&#39;s</strong> URL and publishable key, and type your table&#39;s name.</li><li>Open <strong>Testing your own table instead?</strong> and describe a row in JSON that matches your columns, for example <code>{&quot;name&quot;: &quot;Mallory&quot;, &quot;message&quot;: &quot;Hello&quot;}</code> for Pattern A.</li><li>Try each operation. Everything your B1.1 table says &quot;no&quot; to must come back <strong>REFUSED</strong> or <strong>0 ROWS</strong>. Anything it says &quot;yes&quot; to should be <strong>ALLOWED</strong>. An <strong>ERROR: COLUMN NOT FOUND</strong> means your JSON doesn&#39;t match the table: fix it and try again.</li><li>&quot;0 rows&quot; only proves something if the table holds rows the public shouldn&#39;t see. If your rules hide any rows, add one in the Table Editor and check it stays hidden.</li><li>Fill in the &quot;authorization is enforced in&quot; line of <code>SECURITY_CHECKLIST.md</code>, for example <em>&quot;in the RLS policies and grants on <code>public.messages</code>, in <code>supabase/policies.sql</code>&quot;</em>.</li><li>Copy the page&#39;s results table into <code>SECURITY_CHECKLIST.md</code> as evidence.</li><li>Commit <code>supabase/policies.sql</code>, <code>public/config.js</code> and the checklist on your branch.</li></ol><p>✅ <strong>Checkpoint:</strong> your own attack fails wherever your rules say &quot;no&quot;, the grants match your rules, and the checklist names where authorization is enforced.</p><h3 id="part-b2--connect-one-feature-with-the-agent-core-20-min" tabindex="-1">Part B2 — Connect one feature with the agent (Core, 20 min) <a class="header-anchor" href="#part-b2--connect-one-feature-with-the-agent-core-20-min" aria-label="Permalink to &quot;Part B2 — Connect one feature with the agent (Core, 20 min)&quot;">​</a></h3><p>🟢 AI on, approvals on. Follow the Safe Loop with its two habits: <strong>check first</strong>, then <strong>teach back</strong>. Whatever you don&#39;t finish here is the start of your homework.</p><ol><li><p><strong>Check first (3 min).</strong> The database call needs the network, so its check is a manual one: write it in <code>TESTS.md</code> before you prompt, for example <em>&quot;Add a message, reload the page, it&#39;s still there. Turn off the network in DevTools, add a message, see a friendly error.&quot;</em> Any pure logic (checking a message before it&#39;s sent, formatting a row) gets an automated test in <code>tests/</code> first, as in week 11.</p></li><li><p><strong>Prompt the agent</strong> in plan mode first. Change the table and column names to yours:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: Show the latest messages and let a visitor add one, using getDb() from public/lib/db.js.</span></span>
<span class="line"><span>Context: Capstone starter. The table public.messages (id, name, message, created_at) exists and</span></span>
<span class="line"><span>its rules are in supabase/policies.sql. public/config.js holds the project URL and publishable</span></span>
<span class="line"><span>key. The starter README&#39;s &quot;Feature patterns&quot; section shows the read and insert calls.</span></span>
<span class="line"><span>Constraints: Use only getDb() from public/lib/db.js. Don&#39;t edit supabase/policies.sql or</span></span>
<span class="line"><span>public/config.js. Don&#39;t add npm packages or any other key. Show user text with textContent,</span></span>
<span class="line"><span>never innerHTML. Show a loading message while waiting and a friendly message if a request fails.</span></span>
<span class="line"><span>Show me the plan and wait for my OK.</span></span>
<span class="line"><span>Done when: a message I add is still there after a reload, npm test passes, and a failed request</span></span>
<span class="line"><span>shows a message instead of freezing.</span></span></code></pre></div></li><li><p>Read the plan, approve it (or correct it), then let it make the change. <strong>Read the diff.</strong> The calls use <code>await</code>, as in Python&#39;s <code>async</code> code: a missing <code>await</code> gives you a Promise instead of rows.</p></li><li><p>Run your check from step 1 with <code>npm run dev</code>. Run <code>npm test</code>.</p></li><li><p><strong>Teach back (2 min):</strong> in <code>PROMPTS.md</code>, write 2–3 sentences in your own words: what changed and why. Then commit, with an <code>Assisted-by: [tool]</code> line.</p></li><li><p>Push the branch and open a pull request. You merge it in homework, once it works and you&#39;ve reviewed it.</p></li></ol><p>✅ <strong>Checkpoint:</strong> your data survives a reload, <code>npm test</code> passes, and the commit has a teach-back in <code>PROMPTS.md</code>.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Blank list and a red error in the Console? Check the error&#39;s words against the three answers in A1.6. &quot;Permission denied&quot; means a missing grant (fix it in <code>policies.sql</code>); &quot;0 rows&quot; with data in the Table Editor means a missing or too-strict select policy. More: <a href="./../../resources/troubleshooting.html#supabase">Troubleshooting: Supabase</a>.</p></div><h3 id="part-b3--per-user-rows-or-attack-from-the-console-if-time" tabindex="-1">Part B3 — Per-user rows, or attack from the Console (If time) <a class="header-anchor" href="#part-b3--per-user-rows-or-attack-from-the-console-if-time" aria-label="Permalink to &quot;Part B3 — Per-user rows, or attack from the Console (If time)&quot;">​</a></h3><p>Pick one.</p><ul><li><strong>Per-user rows with Supabase Auth.</strong> Make a table where each signed-in user sees only their own rows. Start from the starter&#39;s Pattern B (<code>notes</code>), or follow the kit&#39;s <a href="https://github.com/Boyu-Zhang-UOI/vc101-rls-lab/blob/main/README.md#stretch-per-user-private-notes" target="_blank" rel="noreferrer">per-user stretch</a> and write the four policies yourself using <code>(select auth.uid()) = user_id</code>. Turn on <strong>Anonymous Sign-Ins</strong> (under <strong>Authentication</strong>; menus move) to test without building a login. This is the pattern for any capstone with private data.</li><li><strong>Attack from the Console, like a stranger would.</strong> Your publishable key is in your live site&#39;s source, so anyone can use it from their browser&#39;s DevTools Console, not only from the attack page. Ask your assistant to explain each line of a short supabase-js snippet that tries to update and delete every row of your table, then run it <strong>on your own live site</strong> and read the result using the three answers from A1.6. Expected: &quot;permission denied&quot; for anything you didn&#39;t grant.</li></ul><h4 id="troubleshooting-studio-b" tabindex="-1">Troubleshooting (Studio B) <a class="header-anchor" href="#troubleshooting-studio-b" aria-label="Permalink to &quot;Troubleshooting (Studio B)&quot;">​</a></h4><ul><li><strong>&quot;permission denied for table …&quot;:</strong> the table has no grant for that operation. Add it in <code>supabase/policies.sql</code> with RLS and a policy, and re-run the whole file.</li><li><strong>RLS on, but the page reads nothing:</strong> RLS with no policies blocks everyone. Add the select policy your B1.1 table calls for.</li><li><strong><code>getDb()</code> refuses to start:</strong> <code>public/config.js</code> holds a secret key, or still has the example&#39;s placeholder. Paste the <code>sb_publishable_</code> key.</li><li><strong>The project is paused:</strong> free projects pause after about a week without activity. Open the dashboard and restore it (<a href="./../../resources/troubleshooting.html#supabase">Troubleshooting: Supabase</a>).</li><li><strong>The agent wants to edit <code>policies.sql</code> or add a grant:</strong> reject that step. You decide the rules; the agent writes page code.</li></ul><hr><h2 id="wrap-up" tabindex="-1">Wrap up <a class="header-anchor" href="#wrap-up" aria-label="Permalink to &quot;Wrap up&quot;">​</a></h2><ul><li>Commit everything on your branch: <code>supabase/policies.sql</code>, <code>public/config.js</code>, your page code, and the <code>SECURITY_CHECKLIST.md</code> evidence (your before/after table, your own table&#39;s results, the &quot;authorization is enforced in&quot; sentence).</li><li>Update <a href="./../../templates/PROMPTS.html">PROMPTS.md template</a>: a teach-back for every agent commit.</li><li>Do the week 13 exit ticket, AI off (🔴). It&#39;s graded on completion, not correctness.</li><li>Homework: <a href="./homework.html">Week 13 homework — Persist it, and prove who can reach it</a>.</li></ul>`,82)])])}const b=t(n,[["render",r]]);export{p as __pageData,b as default};
